function clean(s) {
  return s.trim().toLowerCase();
}

function hasBadWord(message, bad) {
  const m = message.toLowerCase();
  return bad.some(w => m.includes(w));
}

function initials(fullName) {
  return fullName.split(" ").map(w => w[0].toUpperCase()).join("");
}

function row(name, score) {
  return name.padEnd(10, ".") + String(score).padStart(5, " ");
}

function prices(items) {
  return items.map(it => it.price);
}

function passed(scores) {
  return scores.filter(s => s >= 50);
}

function byId(users, id) {
  return users.find(u => u.id === id)?.name ?? "Unknown";
}

function bestTotal(orders) {
  return orders.filter(o => o.paid).map(o => o.amount).reduce((a, b) => a + b, 0);
}

function between(min, max, r) {
  return Math.floor(r * (max - min + 1)) + min;
}

function pick(list, r) {
  return list[Math.floor(r * list.length)];
}

function chance(percent, r) {
  return r < percent / 100;
}

function teams(names, rolls) {
  const t = { red: [], blue: [] };
  names.forEach((n, i) => {
    if (rolls[i] < 0.5) t.red.push(n);
    else t.blue.push(n);
  });
  return t;
}

function weekday(year, month, day) {
  const names = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
  return names[new Date(year, month - 1, day).getDay()];
}

function daysBetween(from, to) {
  const day = 1000 * 60 * 60 * 24;
  return Math.round((new Date(to) - new Date(from)) / day);
}

function isoDate(year, month, day) {
  const m = String(month).padStart(2, "0");
  const d = String(day).padStart(2, "0");
  return year + "-" + m + "-" + d;
}

function untilBirthday(today, month, day) {
  const now = new Date(today);
  const iso = y => y + "-" + String(month).padStart(2, "0") + "-" + String(day).padStart(2, "0");
  let next = new Date(iso(now.getUTCFullYear()));
  if (next < now) next = new Date(iso(now.getUTCFullYear() + 1));
  return Math.round((next - now) / (1000 * 60 * 60 * 24));
}

function makeUser(name, age) {
  return { name, age, active: true };
}

