function withDefaults(options) {
  return { sound: true, volume: 50, theme: "light", ...options };
}

function label(item) {
  const { name, qty = 1 } = item;
  return qty + " × " + name;
}

function describe(stats) {
  return Object.entries(stats).map(([k, v]) => k + ": " + v).join(", ");
}

function unique(list) {
  return [...new Set(list)];
}

