function firstRepeat(list) {
  const seen = new Set();
  for (const x of list) {
    if (seen.has(x)) return x;
    seen.add(x);
  }
  return null;
}

function common(a, b) {
  const inB = new Set(b);
  return [...new Set(a.filter(x => inB.has(x)))];
}

function absent(roster, present) {
  const here = new Set(present);
  return roster.filter(name => !here.has(name));
}

function pages(items, perPage) {
  return Math.ceil(items / perPage);
}

