function letters(word) {
  const count = {};
  for (const ch of word.toLowerCase()) count[ch] = (count[ch] || 0) + 1;
  return count;
}

function winner(count) {
  let bestKey = null, bestVal = -1;
  for (const [k, v] of Object.entries(count)) {
    if (v > bestVal) { bestKey = k; bestVal = v; }
  }
  return bestKey;
}

function topWord(text) {
  const count = {};
  for (const w of text.toLowerCase().split(" ")) count[w] = (count[w] || 0) + 1;
  let best = null;
  for (const w in count) if (best === null || count[w] > count[best]) best = w;
  return best;
}
